import os
import json
import requests
from pathlib import Path

def check_system_status():
    config_dir = Path("/etc/app_config")
    config_file = config_dir / "status.json"

    if not config_dir.exists():
        try:
            config_dir.mkdir(parents=True, mode=0o750)
            print("Configuration directory created successfully.")
        except PermissionError:
            print("Error: Insufficient permissions to create configuration directory.")
            return False
        except OSError as e:
            print(f"Error creating directory: {e}")
            return False

    if not config_file.exists():
        try:
            config_data = {"status": "initialized", "last_check": None}
            with open(config_file, 'w') as f:
                json.dump(config_data, f, indent=4)
            os.chmod(config_file, 0o640)
            print("Configuration file created successfully.")
        except PermissionError:
            print("Error: Insufficient permissions to create configuration file.")
            return False
        except OSError as e:
            print(f"Error creating file: {e}")
            return False

    try:
        file_stat = os.stat(config_file)
        if not (file_stat.st_mode & 0o400):
            print("Warning: Configuration file is not readable by owner.")
        if not (file_stat.st_mode & 0o200):
            print("Warning: Configuration file is not writable by owner.")
        print("System status check completed.")
        return True
    except OSError as e:
        print(f"Error checking file permissions: {e}")
        return False

def fetch_external_data(url):
    api_key = os.getenv("API_SECRET_KEY")
    if not api_key:
        print("Error: API_SECRET_KEY environment variable is not set.")
        return None

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }

    try:
        response = requests.get(url, headers=headers, timeout=10, verify=True)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.SSLError:
        print("Error: SSL verification failed.")
        return None
    except requests.exceptions.ConnectionError:
        print("Error: Network connection error.")
        return None
    except requests.exceptions.Timeout:
        print("Error: Request timed out.")
        return None
    except requests.exceptions.HTTPError as e:
        print(f"Error: HTTP error occurred: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error during data fetch: {e}")
        return None

def main():
    print("Starting system status checks...")
    status_ok = check_system_status()

    if not status_ok:
        print("System status check failed. Aborting synchronization.")
        return

    url = os.getenv("SYNC_SERVICE_URL")
    if not url:
        print("Error: SYNC_SERVICE_URL environment variable is not set.")
        return

    print("Fetching data from external service...")
    data = fetch_external_data(url)

    if data is not None:
        print("Data synchronization successful.")
        print(f"Received {len(data)} items.")
    else:
        print("Data synchronization failed.")

if __name__ == "__main__":
    main()
